cssCode:
.parallax-wrap {
  height: 250vh;
  position: relative;
}
.parallax-sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.parallax-text {
  font-size: 80px;
  font-weight: 900;
  color: #fff;
  font-family: sans-serif;
  mix-blend-mode: difference;
  z-index: 10;
}
.parallax-img-box {
  position: absolute;
  width: 200px;
  height: 300px;
  background: linear-gradient(135deg, #00d2ff, #3a7bd5);
  border-radius: 20px;
  overflow: hidden;
  transform: translateY(100vh); /* શરૂઆતમાં નીચે હશે */
  transition: transform 0.1s linear, width 0.1s linear, height 0.1s linear;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#050505;';

const wrap = document.createElement('div');
wrap.className = 'parallax-wrap';

const sticky = document.createElement('div');
sticky.className = 'parallax-sticky';

const text = document.createElement('div');
text.className = 'parallax-text';
text.innerText = 'BEAUTY';

const imgBox = document.createElement('div');
imgBox.className = 'parallax-img-box';

sticky.appendChild(imgBox);
sticky.appendChild(text);
wrap.appendChild(sticky);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = c.scrollTop / maxScroll;

  // નીચેથી ફોટો ઉપર આવશે
  const yPos = Math.max(0, 100 - (progress * 200));

  // જો વચ્ચે પહોંચે તો ફોટો આખી સ્ક્રીનમાં ફેલાઈ જશે
  let w = 200;
  let h = 300;
  if (progress > 0.4) {
    const expand = (progress - 0.4) * 5; // ઝૂમ મલ્ટીપ્લાયર
    w = Math.min(window.innerWidth, 200 + (expand * window.innerWidth));
    h = Math.min(window.innerHeight, 300 + (expand * window.innerHeight));
  }

  imgBox.style.transform = `translateY(${yPos}vh)`;
  imgBox.style.width = `${w}px`;
  imgBox.style.height = `${h}px`;
});
